    static List<Rect> BuildCandidates(Rect source,Rect[] fixedRooms,double sw,double sd){double maxW=sw-2*Margin,maxD=sd-2*Margin;var widths=new SortedSet<double>();for(double w=Math.Ceiling((source.Area/maxD)/Grid)*Grid;w<=maxW+Tol;w=Math.Round(w+Grid,8))widths.Add(w);widths.Add(source.W);widths.Add(maxW);var rows=new List<Rect>();foreach(double w in widths){double d=Math.Abs(w-source.W)<Tol?source.D:source.Area/w;if(d<=0||d>maxD+Tol)continue;foreach(double y in Positions(Margin,sd-Margin-d))foreach(double x in Positions(Margin,sw-Margin-w)){var q=new Rect("L-01",x,y,w,d);if(Inside(q,sw,sd,Margin)&&!fixedRooms.Any(o=>Overlap(q,o)))rows.Add(q);}}return rows.GroupBy(q=>$"{q.X:F6}|{q.Y:F6}|{q.W:F6}|{q.D:F6}").Select(g=>g.First()).OrderBy(q=>Move(source,q)).ThenBy(q=>q.Y).ThenBy(q=>q.X).ToList();}
    static IEnumerable<double> Positions(double lo,double hi){var r=new SortedSet<double>();for(double v=lo;v<=hi+Tol;v=Math.Round(v+Grid,8))r.Add(v);r.Add(lo);r.Add(hi);return r.Where(v=>v>=lo-Tol&&v<=hi+Tol).Select(v=>Math.Round(v,8));}    static IEnumerable<Rect> Transform(Shape s,double x,double y,int rot){foreach(var p in s.Pieces){double px=p.X,py=p.Y,pw=p.W,pd=p.D;double tx,ty,tw,td;switch(rot){case 0:tx=px;ty=py;tw=pw;td=pd;break;case 1:tx=s.D-py-pd;ty=px;tw=pd;td=pw;break;case 2:tx=s.W-px-pw;ty=s.D-py-pd;tw=pw;td=pd;break;default:tx=py;ty=s.W-px-pw;tw=pd;td=pw;break;}yield return new Rect(p.Id,x+tx,y+ty,tw,td);}}
