    static string MakeSvg(Candidate[] opts,Rect[] fixedRooms,Rect[] windows,Rect src,double sw,double sd){const double k=12,pad=28,head=42,gap=24;int n=Math.Max(1,opts.Length);double pw=sw*k+2*pad,ph=sd*k+head+pad;if(opts.Length==0)return XDocument.Parse($"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{F(pw)}\" height=\"{F(ph)}\"><text x=\"12\" y=\"20\">No L-turn spatial proxy fits the bounded room/window/L-01 screen. No stair access or code finding.</text></svg>").ToString(SaveOptions.DisableFormatting);var s=new StringBuilder($"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{F(pw*n+gap*(n-1))}\" height=\"{F(ph)}\" viewBox=\"0 0 {F(pw*n+gap*(n-1))} {F(ph)}\"><style>text{{font:10px Arial}}.room{{fill:#dce8ed;stroke:#24566c}}.win{{fill:#f7d9f0;stroke:#83366e;stroke-dasharray:4 2}}.stair{{fill:#f5e5b8;stroke:#7c5d11;stroke-width:2}}.shell{{fill:none;stroke:#222;stroke-width:2}}</style>");for(int i=0;i<n;i++){double ox=i*(pw+gap),sx=ox+pad,sy=head+pad;s.AppendLine($"<text x=\"{F(ox+pad)}\" y=\"16\">M302 {i+1}: L move {F(opts[i].Move)} ft; turn proxy, unselected</text>");foreach(var r in fixedRooms)Draw(r,"room",r.Id);Draw(opts[i].L,"room","L-01 same area");foreach(var w in windows)Draw(w,"win",w.Id);foreach(var p in Transform(opts[i].Shape,opts[i].X,opts[i].Y,opts[i].Rotation))Draw(p,"stair",p.Id);s.AppendLine($"<rect class=\"shell\" x=\"{F(sx)}\" y=\"{F(sy)}\" width=\"{F(sw*k)}\" height=\"{F(sd*k)}\"/>");void Draw(Rect r,string cl,string label){double xx=sx+r.X*k,yy=sy+(sd-r.Y-r.D)*k;s.AppendLine($"<rect class=\"{cl}\" x=\"{F(xx)}\" y=\"{F(yy)}\" width=\"{F(r.W*k)}\" height=\"{F(r.D*k)}\"/><text x=\"{F(xx+2)}\" y=\"{F(yy+11)}\">{System.Security.SecurityElement.Escape(label)}</text>");}}s.AppendLine($"<text x=\"8\" y=\"{F(ph-5)}\">Spatial envelope only; 3+4 run split is unverified; no stair access/route or compliance finding.</text></svg>");return XDocument.Parse(s.ToString()).ToString(SaveOptions.DisableFormatting);}
    static double Move(Rect a,Rect b)=>Math.Abs(a.X-b.X)+Math.Abs(a.Y-b.Y)+Math.Abs(a.W-b.W)+Math.Abs(a.D-b.D);static double Gap(Rect a,Rect b)=>Math.Sqrt(Math.Pow(Math.Max(0,Math.Max(a.X-b.R,b.X-a.R)),2)+Math.Pow(Math.Max(0,Math.Max(a.Y-b.T,b.Y-a.T)),2));static double Intersection(Rect a,Rect b)=>Math.Max(0,Math.Min(a.R,b.R)-Math.Max(a.X,b.X))*Math.Max(0,Math.Min(a.T,b.T)-Math.Max(a.Y,b.Y));static bool Overlap(Rect a,Rect b)=>Intersection(a,b)>Tol;static bool Inside(Rect a,double w,double d,double m)=>a.X>=m-Tol&&a.Y>=m-Tol&&a.R<=w-m+Tol&&a.T<=d-m+Tol;
